CREATE TABLE libraries (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT, library_type TEXT NOT NULL CHECK(library_type IN ('MOVIE','TV_SHOW')), privacy TEXT NOT NULL CHECK(privacy IN ('PUBLIC','PRIVATE')), password_hash TEXT, minimum_age INTEGER NOT NULL CHECK(minimum_age BETWEEN 0 AND 21), metadata_language TEXT NOT NULL, metadata_region TEXT, is_active INTEGER NOT NULL DEFAULT 1, scan_enabled INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, last_scan_at TEXT, last_successful_scan_at TEXT, deleted_at TEXT);
CREATE TABLE library_paths (id TEXT PRIMARY KEY, library_id TEXT NOT NULL REFERENCES libraries(id) ON DELETE CASCADE, path TEXT NOT NULL, normalized_path TEXT NOT NULL, is_active INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'AVAILABLE', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, last_scan_at TEXT, UNIQUE(library_id, normalized_path));
CREATE TABLE scan_jobs (id TEXT PRIMARY KEY, library_id TEXT NOT NULL REFERENCES libraries(id), status TEXT NOT NULL, scan_type TEXT NOT NULL, started_at TEXT, finished_at TEXT, discovered_files INTEGER NOT NULL DEFAULT 0, processed_files INTEGER NOT NULL DEFAULT 0, matched_files INTEGER NOT NULL DEFAULT 0, unmatched_files INTEGER NOT NULL DEFAULT 0, skipped_files INTEGER NOT NULL DEFAULT 0, removed_files INTEGER NOT NULL DEFAULT 0, failed_files INTEGER NOT NULL DEFAULT 0, progress REAL NOT NULL DEFAULT 0, error_message TEXT, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, discovery_ms INTEGER NOT NULL DEFAULT 0, matching_ms INTEGER NOT NULL DEFAULT 0, persistence_ms INTEGER NOT NULL DEFAULT 0, tmdb_requests INTEGER NOT NULL DEFAULT 0, tmdb_cache_hits INTEGER NOT NULL DEFAULT 0, db_batches INTEGER NOT NULL DEFAULT 0);
CREATE TABLE media_items (id TEXT PRIMARY KEY, library_id TEXT NOT NULL REFERENCES libraries(id), media_type TEXT NOT NULL, tmdb_id INTEGER NOT NULL, title TEXT NOT NULL, original_title TEXT, overview TEXT, original_language TEXT, release_date TEXT, year INTEGER, poster_path TEXT, backdrop_path TEXT, rating REAL, vote_count INTEGER, popularity REAL, adult INTEGER NOT NULL DEFAULT 0, metadata_language TEXT NOT NULL, metadata_source TEXT NOT NULL, metadata_fetched_at TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(library_id, media_type, tmdb_id));
CREATE TABLE media_files (id TEXT PRIMARY KEY, library_id TEXT NOT NULL REFERENCES libraries(id), library_path_id TEXT NOT NULL REFERENCES library_paths(id), media_item_id TEXT REFERENCES media_items(id), tv_episode_id TEXT, absolute_path TEXT NOT NULL, relative_path TEXT NOT NULL, filename TEXT NOT NULL, extension TEXT NOT NULL, file_size INTEGER NOT NULL, modified_at TEXT NOT NULL, filesystem_identity TEXT, content_type TEXT NOT NULL, scan_status TEXT NOT NULL, identification_status TEXT NOT NULL, normalized_title TEXT, parsed_year INTEGER, parsed_season INTEGER, parsed_episode INTEGER, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, missing_since TEXT, UNIQUE(library_id, absolute_path));
CREATE TABLE movies (media_item_id TEXT PRIMARY KEY REFERENCES media_items(id) ON DELETE CASCADE, runtime INTEGER, status TEXT, tagline TEXT, collection_tmdb_id INTEGER, collection_name TEXT, production_companies TEXT, production_countries TEXT, spoken_languages TEXT, external_ids TEXT, keywords TEXT);
CREATE TABLE tv_shows (media_item_id TEXT PRIMARY KEY REFERENCES media_items(id) ON DELETE CASCADE, last_air_date TEXT, status TEXT, show_type TEXT, number_of_seasons INTEGER, number_of_episodes INTEGER, networks TEXT, creators TEXT, production_companies TEXT, external_ids TEXT);
CREATE TABLE tv_seasons (id TEXT PRIMARY KEY, tv_show_id TEXT NOT NULL REFERENCES media_items(id) ON DELETE CASCADE, tmdb_id INTEGER, season_number INTEGER NOT NULL, name TEXT, overview TEXT, air_date TEXT, poster_path TEXT, episode_count INTEGER, UNIQUE(tv_show_id, season_number));
CREATE TABLE tv_episodes (id TEXT PRIMARY KEY, tv_show_id TEXT NOT NULL REFERENCES media_items(id) ON DELETE CASCADE, season_id TEXT NOT NULL REFERENCES tv_seasons(id) ON DELETE CASCADE, tmdb_id INTEGER, season_number INTEGER NOT NULL, episode_number INTEGER NOT NULL, name TEXT, overview TEXT, air_date TEXT, still_path TEXT, rating REAL, vote_count INTEGER, runtime INTEGER, UNIQUE(season_id, episode_number));
CREATE TABLE genres (id TEXT PRIMARY KEY, tmdb_id INTEGER NOT NULL UNIQUE, name TEXT NOT NULL);
CREATE TABLE media_genres (media_item_id TEXT NOT NULL REFERENCES media_items(id) ON DELETE CASCADE, genre_id TEXT NOT NULL REFERENCES genres(id), PRIMARY KEY(media_item_id, genre_id));
CREATE TABLE people (id TEXT PRIMARY KEY, tmdb_id INTEGER NOT NULL UNIQUE, name TEXT NOT NULL, profile_path TEXT, known_for_department TEXT);
CREATE TABLE credits (id TEXT PRIMARY KEY, media_item_id TEXT NOT NULL REFERENCES media_items(id) ON DELETE CASCADE, person_id TEXT NOT NULL REFERENCES people(id), credit_type TEXT NOT NULL, character_name TEXT, job TEXT, department TEXT, credit_order INTEGER, UNIQUE(media_item_id, person_id, credit_type, character_name, job));
CREATE TABLE metadata_cache (provider TEXT NOT NULL, request_key TEXT NOT NULL, response_type TEXT NOT NULL, entity_id INTEGER, language TEXT NOT NULL, payload TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(provider, request_key, language));
CREATE INDEX idx_library_paths_library ON library_paths(library_id); CREATE INDEX idx_scans_library ON scan_jobs(library_id, created_at); CREATE INDEX idx_media_files_library ON media_files(library_id); CREATE INDEX idx_media_files_path ON media_files(library_path_id); CREATE INDEX idx_media_files_identification ON media_files(identification_status); CREATE INDEX idx_media_files_seen ON media_files(last_seen_at); CREATE INDEX idx_media_files_modified ON media_files(modified_at); CREATE INDEX idx_media_items_library ON media_items(library_id, media_type); CREATE INDEX idx_media_items_tmdb ON media_items(tmdb_id); CREATE INDEX idx_episodes_show_numbers ON tv_episodes(tv_show_id, season_number, episode_number); CREATE INDEX idx_credits_media ON credits(media_item_id); CREATE INDEX idx_credits_person ON credits(person_id);
